<script setup lang="ts">
import{onMounted,ref}from'vue';const question=ref(''),result=ref<any>(null),audits=ref<any[]>([]),busy=ref(false),error=ref('');const headers=()=>({Authorization:'Bearer '+sessionStorage.getItem('ops-token'),'Content-Type':'application/json'});async function loadAudits(){const r=await fetch('/api/admin/analytics/audits',{headers:headers()}),b=await r.json();if(r.ok)audits.value=b.data}async function query(){busy.value=true;error.value='';result.value=null;try{const r=await fetch('/api/admin/analytics/query',{method:'POST',headers:headers(),body:JSON.stringify({question:question.value})}),b=await r.json();if(!r.ok)throw Error(b.message);result.value=b.data;await loadAudits()}catch(e){error.value=e instanceof Error?e.message:'分析失败';await loadAudits()}finally{busy.value=false}}onMounted(loadAudits);
</script>
<template><section><div class="assistant-head"><div><span class="eyebrow">SAFE TEXT-TO-SQL</span><h1>智能数据分析</h1><p class="muted">仅管理员可用。候选 SQL 通过 AST 白名单审核后，由只读账号执行。</p></div></div><div class="analytics-query"><form @submit.prevent="query"><textarea v-model="question" required maxlength="300" rows="2" placeholder="例如：最近 30 天故障次数最多的服务有哪些？"/><button :disabled="busy||!question.trim()">{{busy?'生成并审核中…':'开始分析'}}</button></form><button class="outline" @click="question='最近 30 天故障次数最多的服务有哪些？'">使用演示问题</button></div><p v-if="error" class="banner error">安全审核未通过：{{error}}</p><section v-if="result" class="analytics-result"><div class="audit-strip"><span>✓ AST 审核通过</span><span>✓ 只读账号执行</span><span>✓ 100 行 / 3 秒</span><span>审计 #{{result.auditId}}</span></div><article class="sql-card"><small>最终执行 SQL</small><pre>{{result.generatedSql}}</pre></article><p class="tool-explanation">{{result.summary}}</p><div class="result-table"><table><thead><tr><th v-for="c in result.columns">{{c}}</th></tr></thead><tbody><tr v-for="row in result.rows"><td v-for="c in result.columns">{{row[c]??'—'}}</td></tr></tbody></table><p v-if="!result.rowCount" class="empty">没有符合条件的数据</p></div></section><section class="audit-panel"><div class="panel-title"><h2>最近 SQL 审计</h2><small>成功与拦截均保留</small></div><article v-for="a in audits" class="audit-row"><div><b>{{a.QUESTION}}</b><small>{{a.CREATED_AT}} · {{a.LATENCY_MS??0}} ms · {{a.ROW_COUNT}} 行</small></div><span :class="a.EXECUTION_STATUS==='SUCCESS'?'audit-ok':'audit-fail'">{{a.VALIDATION_STATUS}} / {{a.EXECUTION_STATUS}}</span><code v-if="a.GENERATED_SQL">{{a.GENERATED_SQL}}</code><small v-if="a.FAILURE_REASON" class="error">{{a.FAILURE_REASON}}</small></article><div v-if="!audits.length" class="empty">暂无分析记录</div></section></section></template>
